<?php use VazinCMS\Security; ?><section class="title"><div><h1>#<?=$ticket['id']?> — <?=Security::e($ticket['subject'])?></h1><p><?=Security::e((string)$ticket['customer'])?> · <?=Security::e((string)$ticket['email'])?></p></div><a class="button secondary" href="/admin/tickets">بازگشت</a></section><section class="ticket-layout"><div><?php foreach($messages as $m):?><article class="message <?=$m['is_internal']?'internal':''?>"><div><b><?=Security::e((string)($m['author']??'کاربر حذف‌شده'))?></b><span><?=$m['is_internal']?'یادداشت داخلی':'پیام'?> · <?=Security::e((string)$m['created_at'])?></span></div><p><?=nl2br(Security::e($m['body']))?></p></article><?php endforeach;?><section class="panel"><h2>پاسخ یا یادداشت</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><textarea name="body" rows="6" required></textarea><label class="check"><input type="checkbox" name="internal" value="1"> یادداشت داخلی؛ مشتری نمی‌بیند</label><button>ثبت</button></form></section></div><aside class="panel"><h2>تنظیمات تیکت</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="update"><label>وضعیت<select name="status"><?php foreach(['open'=>'باز','answered'=>'پاسخ داده‌شده','customer_reply'=>'پاسخ مشتری','closed'=>'بسته'] as $v=>$l):?><option value="<?=$v?>" <?=$ticket['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>اولویت<select name="priority"><?php foreach(['low'=>'کم','normal'=>'عادی','high'=>'زیاد','urgent'=>'فوری'] as $v=>$l):?><option value="<?=$v?>" <?=$ticket['priority']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button>به‌روزرسانی</button></form></aside></section>
